// One interaction across menus: inspect on the left, act on the right.
const iconMenuMemory={};
const MENU_SYMBOLS={weapon:'⚔',armor:'♜',shield:'⛨',helmet:'♙',gloves:'✋',boots:'➟',belt:'═',amulet:'◇',ring1:'○',ring2:'◎',hunt:'⚔',boss:'♛',trial:'✦',secret:'☽',ex:'✹',storage:'▣',bag:'▤',gems:'◆',skills:'✧',sound:'♫',settings:'⚙',help:'?',save:'▣',forge:'⚒',dps:'◴',reactions:'✺',village:'⚑',promotion:'✦'};
const MENU_ICON_PATHS={weapon:'M13 49 46 8 51 8 51 13 20 49 M10 39 27 52 M9 52 15 57',armor:'M21 10 26 15 38 15 43 10 56 20 48 31 43 27 45 55 19 55 21 27 16 31 8 20Z M26 15 28 28 36 28 38 15 M24 38 40 38',shield:'M32 7 51 14 49 37Q43 51 32 57Q21 51 15 37L13 14Z M32 17V43 M23 28H41',helmet:'M15 47V30Q16 12 32 11Q48 12 49 30V47L38 53V36H26V53Z M19 28H45 M32 12V28',gloves:'M20 52 12 33Q11 27 16 28L22 34V15Q24 10 27 15V30 10Q30 5 33 10V30 12Q36 7 39 12V31 18Q43 13 45 19V40L40 53Z',boots:'M20 8 40 8 38 35 53 44 53 53 13 53 13 42 19 33Z M18 20H39 M14 46H52',belt:'M7 24H57V42H7Z M25 20H40V46H25Z M29 33H45',amulet:'M17 9Q20 30 32 36Q44 30 47 9 M32 34 44 46 32 59 20 46Z',ring1:'M23 15 32 7 41 15 32 25Z M23 20Q10 28 17 44Q31 61 47 44Q55 29 41 20',ring2:'M21 17 32 8 43 17 32 28Z M21 23Q10 33 19 47Q32 58 45 47Q54 33 43 23 M22 33Q18 45 32 49Q46 45 42 33'};
function menuIcon(kind){if(MENU_ICON_PATHS[kind])return '<svg class="menu-slot-icon" viewBox="0 0 64 64" aria-hidden="true"><path d="'+MENU_ICON_PATHS[kind]+'"/></svg>';return '<span class="menu-symbol" aria-hidden="true">'+(MENU_SYMBOLS[kind]||'✦')+'</span>'}
function iconTileHtml(label,icon){return icon+'<span class="icon-caption">'+gearEscape(label)+'</span>'}
function iconEnterDetail(pane){if(!pane)return;let target=Array.from(pane.querySelectorAll('button:not(:disabled),select:not(:disabled),input:not(:disabled),textarea,summary')).find(el=>!el.closest('[hidden]'));menuFocusElement(target||pane)}
function iconSelectEntry(key,enter=false){let body=$('card').querySelector('.panel-body'),deck=body?.querySelector('.icon-browser');if(!deck)return;let buttons=Array.from(deck.querySelectorAll('.icon-entry')),button=buttons.find(b=>b.dataset.iconKey===key);if(!button)return;iconMenuMemory[deck.dataset.kind]=key;for(let b of buttons){let selected=b===button;b.classList.toggle('icon-selected',selected);b.setAttribute('aria-current',String(selected));}for(let pane of deck.querySelectorAll('.icon-pane')){let selected=pane.dataset.iconKey===key;if(selected&&pane.hidden)pane.parentElement.scrollTop=0;pane.hidden=!selected;}if(enter)iconEnterDetail(deck.querySelector('.icon-pane:not([hidden])'));}
function makeIconBrowser(kind,entries){
 let body=$('card').querySelector('.panel-body');if(!body||body.querySelector('.icon-browser')||!entries.length)return;
 let deck=document.createElement('div'),list=document.createElement('nav'),detail=document.createElement('aside');deck.className='icon-browser';deck.dataset.kind=kind;list.className='icon-list';list.setAttribute('aria-label','項目一覧');detail.className='icon-detail';detail.setAttribute('aria-label','選択した項目の詳細');deck.append(list,detail);
 for(let entry of entries){let button=entry.button||document.createElement('button'),pane=document.createElement('section');button.type='button';button.tabIndex=0;button.classList.add('icon-entry');button.disabled=false;button.dataset.iconKey=entry.key;button.setAttribute('aria-label',entry.label);button.title=entry.label;button.innerHTML=iconTileHtml(entry.label,entry.icon||menuIcon(kind));button.removeAttribute('onclick');button.onclick=()=>iconSelectEntry(entry.key,true);button.onfocus=()=>iconSelectEntry(entry.key);pane.className='icon-pane';pane.dataset.iconKey=entry.key;pane.tabIndex=-1;pane.hidden=true;let heading=document.createElement('h3');heading.textContent=entry.label;pane.append(heading);for(let node of entry.nodes)pane.append(node);list.append(button);detail.append(pane);}
 body.replaceChildren(deck);body.classList.add('icon-menu-body');let key=entries.some(e=>e.key===iconMenuMemory[kind])?iconMenuMemory[kind]:entries[0].key;iconSelectEntry(key);let button=Array.from(list.children).find(b=>b.dataset.iconKey===key);menuFocusElement(button);
}
function iconActionEntry(button,key,icon,label){let content=document.createElement('div'),action=document.createElement('button');action.textContent=label||button.textContent.trim();let handler=button.getAttribute('onclick');if(handler)action.setAttribute('onclick',handler);action.disabled=button.disabled||button.hasAttribute('disabled');for(let child of Array.from(button.childNodes))content.append(child);return{key,label:label||action.textContent,icon,button,nodes:[content,action]};}
function iconInventory(){
 let cards=inventoryCards();cards.forEach((card,index)=>{if(card.dataset.iconCompact)return;let slot=index<GEAR_SLOTS.length?GEAR_SLOTS[index]:p.bag[index-GEAR_SLOTS.length]?.slot,pane=$('card').querySelector('[data-inventory-detail="'+index+'"]');if(!pane)return;let label=card.querySelector('strong')?.textContent||EQUIPMENT[slot]?.label||'未装備';if(label==='未装備')label=(EQUIPMENT[slot]?.label||'装備')+'（未装備）';pane.querySelector('h3').textContent=label;let anchor=pane.children[1]||null;for(let child of Array.from(card.children)){if(child.tagName==='STRONG')child.remove();else pane.insertBefore(child,anchor);}card.innerHTML=iconTileHtml(EQUIPMENT[slot]?.label||label,(typeof equipmentArt==='function'?equipmentArt(index<GEAR_SLOTS.length?p[slot]:p.bag[index-GEAR_SLOTS.length],slot):menuIcon(slot)));card.dataset.iconCompact='true';card.dataset.rarity=(index<GEAR_SLOTS.length?p[slot]:p.bag[index-GEAR_SLOTS.length])?.rarity||'empty';card.setAttribute('role','button');card.setAttribute('aria-label',(index<GEAR_SLOTS.length?'装備中：':'鞄：')+label);card.title=label;card.addEventListener('focus',()=>{if(inventoryNav.index!==index){inventoryNav.index=index;inventoryNav.actions=false;inventoryFocus()}});});
}
function iconGemMenu(){
 let body=$('card').querySelector('.panel-body');if(!body||body.querySelector('.icon-browser'))return;let entries=[],slots=GEAR_SLOTS.filter(slot=>p[slot]?.sockets.length);
 Array.from(body.querySelectorAll('.equipment > .gearcard')).forEach((node,i)=>entries.push({key:'socket:'+slots[i],label:EQUIPMENT[slots[i]].label+'のソケット',icon:menuIcon(slots[i]),nodes:[node]}));
 Array.from(body.querySelectorAll('.bindings label')).forEach((label,i)=>{let box=document.createElement('div'),note=label.nextElementSibling;box.className='bindings icon-binding';box.append(label);if(note?.tagName==='P')box.append(note);entries.push({key:'binding:'+i,label:'スキル枠 '+(i+1),icon:p.bindings[i]?gemIcon(p.bindings[i]):menuIcon('gems'),nodes:[box]});});
 Array.from(body.querySelectorAll('.gemcard')).forEach((button,i)=>{let gem=p.gems[i],entry=iconActionEntry(button,'gem:'+i,gemIcon(gem.type),gemDisplayName(gem));entry.nodes[0].classList.add('gem-description');entry.nodes.at(-1).textContent='このジェムを装着する';entries.push(entry)});
 let help=document.createElement('div');for(let node of Array.from(body.children))if(!node.matches('.equipment,.bindings,.gemgrid'))help.append(node);entries.push({key:'help',label:'ジェムの使い方・元素反応',icon:menuIcon('help'),nodes:[help]});makeIconBrowser('gems',entries);
}
function iconStashMenu(){let body=$('card').querySelector('.panel-body');if(!body||body.querySelector('.icon-browser'))return;let entries=[];for(let button of body.querySelectorAll('.stash-item')){let stored=button.dataset.stashSide==='storage',items=stored?stashItems():p.bag,index=entries.filter(e=>e.key.startsWith(stored?'storage:':'bag:')).length,it=items[index];let entry=iconActionEntry(button,(stored?'storage:':'bag:')+index,(typeof equipmentArt==='function'?equipmentArt(it):menuIcon(it.slot)),(stored?'倉庫：':'鞄：')+it.name);entry.nodes.at(-1).textContent=stored?'鞄へ取り出す':'倉庫へ預ける';entries.push(entry)}let help=document.createElement('p');help.textContent='倉庫 '+stashItems().length+' / '+STASH_LIMIT+' · 鞄 '+p.bag.length+' / 20。装備を選び、右側で移動を決定します。ジェム・リンク・保護状態は保持されます。';entries.push({key:'help',label:'倉庫と鞄',icon:menuIcon('storage'),nodes:[help]});makeIconBrowser('stash',entries)}
function iconTreeMenu(){let body=$('card').querySelector('.panel-body'),tree=$('treeViewport'),detail=$('nodeDetail');if(!body||!tree||!detail||body.querySelector('.icon-tree'))return;let row=document.createElement('div');row.className='icon-tree';detail.tabIndex=-1;tree.before(row);row.append(tree,detail);body.classList.add('icon-tree-body');for(let node of tree.querySelectorAll('[data-node]'))node.addEventListener('focus',()=>inspectNode(+node.dataset.node));}
function iconPageBrowser(kind,definitions,key,nodes,select){iconMenuMemory[kind]=key;makeIconBrowser(kind,definitions.map(d=>({...d,nodes:d.key===key?nodes:[]})));for(let button of $('card').querySelectorAll('.icon-entry')){let target=button.dataset.iconKey;button.onfocus=()=>{if(target!==key)select(target,false);else iconSelectEntry(target)};button.onclick=()=>{if(target!==key)select(target,true);else iconSelectEntry(target,true)}}}
function iconForgeMenu(){let body=$('card').querySelector('.panel-body');if(!body||body.querySelector('.icon-browser'))return;let links=body.querySelector('.world-tabs');if(links)body.append(links);iconPageBrowser('forge',GEAR_SLOTS.map(slot=>({key:slot,label:EQUIPMENT[slot].label,icon:menuIcon(slot)})),worldForgeSlot,Array.from(body.children),(slot,enter)=>{worldForgeSlot=slot;showForge();if(enter)iconSelectEntry(slot,true)})}
function iconTutorialMenu(){let body=$('card').querySelector('.panel-body');if(!body||body.querySelector('.icon-browser'))return;body.querySelector('.tutorial-progress')?.remove();iconPageBrowser('tutorial',LESSONS.map((lesson,i)=>({key:String(i),label:lesson[1],icon:'<span class="menu-symbol" aria-hidden="true">'+(i+1)+'</span>'})),String(tutorialGuidePage),Array.from(body.children),(key,enter)=>{tutorialShow(+key);if(enter)iconSelectEntry(key,true)})}
function iconReactionMenu(){let body=$('card').querySelector('.panel-body');if(!body||body.querySelector('.icon-browser'))return;body.querySelector('[aria-controls="reactionTable"]')?.remove();body.querySelector('#reactionTable')?.remove();let entries=[{key:'picker',label:'属性を組み合わせる',icon:menuIcon('reactions'),nodes:Array.from(body.children)}];for(let reaction of Object.values(REACTIONS).sort((a,b)=>a.key.length-b.key.length||a.key.localeCompare(b.key))){let description=document.createElement('p'),elements=document.createElement('p');description.textContent=reactionDescription(reaction);elements.textContent=reaction.elements.map(i=>ELEMENTS[i].name).join(' ＋ ');entries.push({key:'reaction:'+reaction.key,label:reaction.name,icon:'<span class="reaction-tile-symbols" aria-hidden="true">'+reaction.elements.map(i=>ELEMENTS[i].icon).join('')+'</span>',nodes:[elements,description]})}makeIconBrowser('reactions',entries)}
// Topics use their actual DOM nodes, so inputs, async account updates and handlers survive.
function iconTopicMenu(kind){return classicMenuLayout(kind)}
function iconQuestEnter(id){inspectGuildQuest(id);iconEnterDetail($('guildQuestDetail'))}
const iconInspectQuestBase=inspectGuildQuest;inspectGuildQuest=id=>{iconInspectQuestBase(id);let q=guildQuest(id),detail=$('guildQuestDetail');if(!q||!detail)return;detail.tabIndex=-1;let title=detail.querySelector('h3');if(title)detail.prepend(title);let status=detail.querySelector('.guild-selection-status');if(status&&guildQuestAllowed(q))status.textContent='内容を確認して受注';let action=document.createElement('button');action.textContent='この依頼を受注する';action.disabled=!guildQuestAllowed(q);action.onclick=()=>activateGuildQuest(id);detail.append(action)};
function iconQuestMenu(){let buttons=$('card').querySelectorAll('[data-guild-quest]');for(let button of buttons){let q=guildQuest(button.dataset.guildQuest);button.innerHTML=iconTileHtml(q.name,menuIcon(q.kind));button.setAttribute('aria-label',q.name);button.title=q.name;button.onclick=()=>iconQuestEnter(q.id);}if(buttons.length){$('card').querySelector('.guild-board').classList.add('icon-quest-board');inspectGuildQuest(guildBoardSelection);}else iconTopicMenu('village')}
function iconSetupMenu(kind){if(!started||dead)return;if(kind==='inventory')iconInventory();else if(kind==='gems')iconGemMenu();else if(kind==='stash')iconStashMenu();else if(kind==='skills')iconTreeMenu();else if(['help','pause'].includes(kind)){if(kind==='pause'&&typeof availableGameRelease!=='undefined'&&availableGameRelease){let action=document.createElement('button');action.textContent='ゲームを更新';action.setAttribute('onclick','showGameUpdate()');$('card').querySelector('.panel-body')?.append(action);}iconTopicMenu(kind);}}
const iconPanelBase=panel;panel=kind=>{iconPanelBase(kind);if(!tutorialGuideOpen)iconSetupMenu(kind)};
const iconVillageBase=showVillage;showVillage=(...args)=>{iconVillageBase(...args);iconQuestMenu()};
const iconForgeBase=showForge;showForge=(...args)=>{let prior=menuSurface==='forge'&&document.activeElement?.closest?.('.icon-pane')?document.activeElement.getAttribute('aria-label'):null;iconForgeBase(...args);iconForgeMenu();if(prior)menuFocusElement(Array.from($('card').querySelectorAll('select')).find(el=>el.getAttribute('aria-label')===prior))};
const iconDpsBase=showDps;showDps=(...args)=>{iconDpsBase(...args);iconTopicMenu('dps')};
const iconSaveBase=showSaveManager;showSaveManager=(...args)=>{iconSaveBase(...args);iconTopicMenu('save')};
const iconSettingsBase=showControllerSettings;showControllerSettings=(...args)=>{iconSettingsBase(...args);iconTopicMenu('settings')};
const iconTutorialBase=tutorialShow;tutorialShow=(...args)=>{iconTutorialBase(...args);classicMenuLayout('tutorial')};
const iconReactionsBase=showReactionGuide;showReactionGuide=(...args)=>{iconReactionsBase(...args);classicMenuLayout('reactions')};
const iconExBase=showExResult;showExResult=(...args)=>{iconExBase(...args);iconTopicMenu('exResult')};
const iconWorldBase=worldMenu;worldMenu=(title,html,kind='village')=>{iconWorldBase(title,html,kind);if(['promotion','update'].includes(kind))iconTopicMenu(kind)};
// Existing socket/binding restoration may target a hidden detail: reveal its pane first.
const iconFocusBase=menuFocusElement;menuFocusElement=el=>{let pane=el?.closest?.('.icon-pane');if(pane)iconSelectEntry(pane.dataset.iconKey);iconFocusBase(el)};
const iconRevealBase=menuReveal;menuReveal=el=>{let pane=el?.closest?.('.icon-list,.icon-detail,#nodeDetail');if(pane){menuRevealWithin(pane,el);iconRevealBase(pane)}else iconRevealBase(el)};
const iconScrollBase=menuScroll;menuScroll=(stick,dt)=>{let deck=$('card').querySelector('.icon-browser'),pane=deck?.querySelector('.icon-detail')||($('card').querySelector('.icon-tree')?$('nodeDetail'):null);if(!pane)return iconScrollBase(stick,dt);padCursor.active=false;if(stick.magnitude>.15)pane.scrollTop+=stick.y*500*dt};
function iconMenuBack(){if(menuSurface==='classSelect'&&!started){welcome();return true;}let active=document.activeElement,pane=active?.closest?.('.icon-pane');if(pane){let button=Array.from($('card').querySelectorAll('.icon-entry')).find(b=>b.dataset.iconKey===pane.dataset.iconKey);menuFocusElement(button);return true;}if(active?.closest?.('#guildQuestDetail')){menuFocusElement($('card').querySelector('[data-guild-quest="'+guildBoardSelection+'"]'));return true;}return false;}
const iconPadBase=padMenu;padMenu=(g,left,right,dt)=>{if(padEdge(g,'back')&&iconMenuBack()){playSound('ui');return;}iconPadBase(g,left,right,dt)};
addEventListener('keydown',event=>{if(event.key==='Escape'&&paused&&iconMenuBack()){event.preventDefault();event.stopImmediatePropagation()}},true);

const iconChooseGemBase=chooseGem;chooseGem=index=>{iconChooseGemBase(index);if(menuSurface!=='gems'||selectedGem===null)return;let gem=p.gems[selectedGem],targets=Array.from($('card').querySelectorAll('[data-socket-slot]')).filter(el=>{let socket=p[el.dataset.socketSlot]?.sockets[+el.dataset.socketIndex];return socket&&(socket.color==='W'||socket.color===GEM[gem.type].color)});targets.sort((a,b)=>Number(!!p[a.dataset.socketSlot].sockets[+a.dataset.socketIndex].gem)-Number(!!p[b.dataset.socketSlot].sockets[+b.dataset.socketIndex].gem));menuFocusElement(targets[0]);};
const iconGemBackBase=menuGemBack;menuGemBack=()=>iconMenuBack()||iconGemBackBase();

const iconHintBase=menuHintText;menuHintText=()=>menuSurface==='inventory'?'十字キー：選択 · A：詳細／決定 · B：戻る · L/R：タブ · 右スティック：説明':iconHintBase();

const iconTagsBase=showTagGuide;showTagGuide=(...args)=>{iconTagsBase(...args);iconTopicMenu('tags')};

function classicMenuLayout(kind){
 let body=$('card').querySelector('.panel-body');if(!body)return;
 body.classList.add('classic-menu-body');body.dataset.menuKind=kind;
 if(['welcome','pause','classSelect'].includes(kind)){
  body.classList.add('classic-action-menu');
  if(kind==='pause'&&!body.querySelector('[data-pause-settings]')){let settings=document.createElement('button');settings.textContent='操作・音の設定';settings.dataset.pauseSettings='true';settings.setAttribute('onclick','showControllerSettings()');body.append(settings);}
  let actions=Array.from(body.children).filter(el=>el.tagName==='BUTTON');
  // Continue first; the original handlers remain on the actual buttons.
  let resume=actions.find(el=>/closePanel\(\)|resume\(\)/.test(el.getAttribute('onclick')||''));
  if(resume)body.prepend(resume);
  menuFocusElement((resume&&!resume.disabled?resume:null)||actions.find(button=>!button.disabled));
 }else if(!body.contains(document.activeElement)){menuFocusElement(body.querySelector('button:not(:disabled),select:not(:disabled),input:not(:disabled),summary'));}
}
const iconWelcomeBase=welcome;
function showClassSelection(){
 iconWelcomeBase();let card=$('card'),choices=Array.from(card.querySelectorAll('button')).filter(button=>/^newGame\(/.test(button.getAttribute('onclick')||''));
 card.innerHTML='<h2>冒険者を選ぶ</h2><p>クラスを選んで、新しい冒険を始めます。</p>';
 for(let button of choices)card.append(button);
 let back=document.createElement('button');back.textContent='タイトルに戻る';back.setAttribute('onclick','welcome()');card.append(back);
 frameMenu('classSelect');classicMenuLayout('classSelect');
}
welcome=()=>{
 iconWelcomeBase();let card=$('card'),buttons=Array.from(card.querySelectorAll('button')),resumeButton=buttons.find(button=>button.getAttribute('onclick')==='resume()');
 let navigation=buttons.filter(button=>!/^newGame\(|^resume\(/.test(button.getAttribute('onclick')||''));
 card.innerHTML='<h2>ASHEN DEPTHS · 灰の深淵</h2>';
 if(resumeButton){let available=false;try{decodeSave(localStorage.getItem(SAVE_KEY));available=true}catch{available=validHistory().length>0}resumeButton.disabled=!available;card.append(resumeButton);}
 let begin=document.createElement('button');begin.textContent='新しい冒険を始める';begin.setAttribute('onclick','showClassSelection()');card.append(begin);
 for(let button of navigation)card.append(button);
 let about=document.createElement('details');about.className='title-about';about.innerHTML='<summary>このゲームについて</summary><p>灯火の村で依頼を受け、素材で装備を作り、昇格試験とEXボスに挑むアクションRPGです。</p><p>自動保存はこのブラウザー内に保存されます。</p><p>Path of Exileに着想を得た非公式の独自作品です。原作コンテンツは収録していません。</p>';card.append(about);
 card.classList.remove('wide');frameMenu('welcome');classicMenuLayout('welcome');
};
if(!started)welcome();

